private fun handleIntentAction(intent: Intent, navigator: Navigator): Boolean {
    val notificationId = intent.getIntExtra("notificationId", -1)
    if (notificationId > -1) {
        NotificationReceiver.dismissNotification(
            applicationContext,
            notificationId,
            intent.getIntExtra("groupId", 0),
        )
    }

    // Кнопка "настройки OCR" из читалки: раньше экстра игнорировалась,
    // и переход просто открывал главный экран. Настройки OCR/озвучки
    // живут в разделе Словарь.
    if (intent.getBooleanExtra("open_ocr_settings", false)) {
        intent.removeExtra("open_ocr_settings")
        navigator.popUntilRoot()
        navigator.push(SettingsScreen(SettingsScreen.Destination.Dictionary))
        ready = true
        return true
    }

    // Кнопка «Открыть AI-чат» в настройках: вкладка живёт в нижней
    // навигации, поэтому идём тем же путём, что и ярлыки рабочего стола.
    if (intent.getBooleanExtra(EXTRA_OPEN_AI_CHAT, false)) {
        intent.removeExtra(EXTRA_OPEN_AI_CHAT)
        if (ocrPreferences.aiTabVisible().get()) {
            navigator.popUntilRoot()
            lifecycleScope.launch { HomeScreen.openTab(HomeScreen.Tab.AiChat) }
            ready = true
            return true
        }
        // Вкладка скрыта — показываем раздел настроек AI, где её можно
        // включить; открывать несуществующую вкладку нельзя.
        navigator.popUntilRoot()
        navigator.push(SettingsScreen(SettingsScreen.Destination.Ai))
        ready = true
        return true
    }

    val tabToOpen = when (intent.action) {
        Constants.SHORTCUT_LIBRARY -> HomeScreen.Tab.Library()
        Constants.SHORTCUT_MANGA -> {
            val idToOpen = intent.extras?.getLong(Constants.MANGA_EXTRA) ?: return false
            navigator.popUntilRoot()
            HomeScreen.Tab.Library(idToOpen)
        }
        Constants.SHORTCUT_UPDATES -> HomeScreen.Tab.Updates
        Constants.SHORTCUT_HISTORY -> HomeScreen.Tab.History
        Constants.SHORTCUT_SOURCES -> HomeScreen.Tab.Browse(false)
        Constants.SHORTCUT_EXTENSIONS -> HomeScreen.Tab.Browse(true)
        Constants.SHORTCUT_DOWNLOADS -> {
            navigator.popUntilRoot()
            HomeScreen.Tab.More(toDownloads = true)
        }
        Intent.ACTION_APPLICATION_PREFERENCES -> {
            navigator.popUntilRoot()
            navigator.push(SettingsScreen())
            null
        }
        Intent.ACTION_SEARCH, Intent.ACTION_SEND, "com.google.android.gms.actions.SEARCH_ACTION" -> {
            // If the intent match the "standard" Android search intent
            // or the Google-specific search intent (triggered by saying or typing "search *query* on *Tachiyomi*" in Google Search/Google Assistant)

            // Get the search query provided in extras, and if not null, perform a global search with it.
            val query = intent.getStringExtra(SearchManager.QUERY) ?: intent.getStringExtra(Intent.EXTRA_TEXT)
            if (!query.isNullOrEmpty()) {
                navigator.popUntilRoot()
                navigator.push(DeepLinkScreen(query))
            }
            null
        }
        INTENT_SEARCH -> {
            val query = intent.getStringExtra(INTENT_SEARCH_QUERY)
            if (!query.isNullOrEmpty()) {
                val filter = intent.getStringExtra(INTENT_SEARCH_FILTER)
                navigator.popUntilRoot()
                navigator.push(GlobalSearchScreen(query, filter))
            }
            null
        }
        Intent.ACTION_VIEW -> {
            // Handling opening of backup files
            if (intent.data.toString().endsWith(".tachibk")) {
                navigator.popUntilRoot()
                navigator.push(RestoreBackupScreen(intent.data.toString()))
            }
            // Deep link to add extension store
            else if (intent.isAddExtensionStoreIntent()) {
                intent.data?.getQueryParameter("url")?.let { repoUrl ->
                    navigator.popUntilRoot()
                    navigator.push(ExtensionStoresScreen(repoUrl))
                }
            }
            null
        }
        else -> return false
    }

    if (tabToOpen != null) {
        lifecycleScope.launch { HomeScreen.openTab(tabToOpen) }
    }

    ready = true
    return true
}

