    val conn = openConnection(actualUrl)
    conn.requestMethod = "POST"
    conn.doOutput = true
    conn.connectTimeout = 15_000
    conn.readTimeout = 90_000
    conn.setRequestProperty("Content-Type", "application/json")
    if (apiKey.isNotBlank()) conn.setRequestProperty("Authorization", "Bearer $apiKey")

    conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
    val code = conn.responseCode
    val text = (if (code in 200..299) conn.inputStream else conn.errorStream)
        ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
    conn.disconnect()
    if (code !in 200..299) {
        // Отдельная судьба для «бесплатных» моделей Zen: OpenCode
        // отдаёт их только своему же клиенту (проверка по User-Agent),
        // поэтому ни ключ, ни прокси, ни ротация тут не помогут. Ловим
        // ДО классификации по коду, иначе 403 уходит в Fatal, и каждая
        // модель каталога получает cooldown — после чего даже рабочий
        // путь выглядит сломанным на 5 минут.
        if (isZenFreeTierBlocked(code, text)) {
            lastFailureMessage = FREE_TIER_BLOCKED_MESSAGE
            noteZenBlocked()
            logcat(LogPriority.WARN) { "Zen free tier blocked for $model (HTTP $code)" }
            return Outcome.FreeTierBlocked
        }
        lastFailureMessage = "$model: HTTP $code — ${text.take(160)}"
        logcat(LogPriority.WARN) { "AI assistant HTTP $code ($model): ${text.take(160)}" }
        addLog(
            LogEntry(
                startedAt, model, userPrompt.take(200),
                "HTTP $code: ${text.take(120)}",
                System.currentTimeMillis() - startedAt,
            ),
        )
        // Классификация: настоящий лимит vs временный сбой vs фатально
        val isLimit = code == 429 ||
            text.contains("FreeUsageLimit", ignoreCase = true) ||
            text.contains("rate_limit", ignoreCase = true) ||
            text.contains("quota", ignoreCase = true)
        return when {
            isLimit -> Outcome.RateLimited
            code in 500..599 || code == 408 -> Outcome.Transient // 5xx/таймаут — прокси/сайт барахлит
            else -> Outcome.Fatal
        }
    }
    // Разбор формы ответа — по семейству модели. Раньше читался
    // только choices[0].message, поэтому у Claude (блок thinking),
    // у Responses (отдельный output) и у Gemini (флаг thought)
    // размышления терялись, и в чате появлялось «🤔 null».
    val parsed = ZenProtocol.parse(text, model)
    val answer = parsed.content
    val reasoning = parsed.reasoning
    addLog(LogEntry(startedAt, model, userPrompt.take(200), (answer ?: "<пусто>").take(200), System.currentTimeMillis() - startedAt))
    answer?.let {
        lastFailureMessage = ""
        Outcome.Ok(
            ChatReply(
                content = it,
                reasoning = reasoning,
                model = model,
                tokens = parsed.tokens,
                complete = parsed.complete,
            ),
        )
    } ?: Outcome.Fatal
} catch (e: Exception) {
