    }
    val handle = findHandle(x, y)
    if (handle != null) {
        mode = Mode.CORNER_RESIZE
        handleIndex = handle
        return true
    }
    if (frame.contains(x, y)) {
        mode = Mode.MOVE
        return true
    }
    return true
}

