                    text = OcrTextCleaner.postprocess(text),
                    left = clamp01(line.minX.toFloat() / w),
                    top = clamp01(line.minY.toFloat() / h),
                    right = clamp01((line.maxX + 1).toFloat() / w),
                    bottom = clamp01((line.maxY + 1).toFloat() / h),
