    private class Cluster {
        val comps = ArrayList<ConnectedComponents.Component>()
        val cells = HashSet<Int>()
        var minX = Int.MAX_VALUE
        var minY = Int.MAX_VALUE
        var maxX = 0
        var maxY = 0

        val width: Int get() = maxX - minX + 1

        val height: Int get() = maxY - minY + 1

