/**
 * Границы текстовых строк, найденные детектором PP-OCRv4, в
 * нормализованных координатах.
 *
 * Тот же проход, что и в [recognizeText], но без распознавания: нужен
 * репозиторию, чтобы построить регионы страницы (по региону на реплику)
 * вместо одного региона на весь лист. Раньше эту роль должен был играть
 * DetOcrEngine, но он оставался заглушкой, и детектор был доступен
 * только изнутри распознавания.
 */
suspend fun detectRegions(image: Bitmap): List<OcrBoundingBox> {
    ensureInitialized()
    OcrStageBus.post(OcrStageBus.Stage.DETECTING)
    return mutex.withLock {
        require(!image.isRecycled) { "Input bitmap is recycled" }
        detectTextBoxes(image).mapNotNull { box ->
            OcrBoxGeometry.normalize(
                left = box.rect.left,
                top = box.rect.top,
                right = box.rect.right,
                bottom = box.rect.bottom,
                imageWidth = image.width,
                imageHeight = image.height,
            )
        }
    }
}

override suspend fun recognizeText(image: Bitmap): String {
    ensureInitialized()
    return try {
    mutex.withLock {
        OcrTextCleanerStats.reset()
        require(!image.isRecycled) { "Input bitmap is recycled" }
        val boxes = detectTextBoxes(image)
        OcrStageBus.post(OcrStageBus.Stage.RECOGNIZING, "боксов: ${boxes.size}")
        if (boxes.isEmpty()) {
            OcrStageBus.post(OcrStageBus.Stage.DONE, "рамки проекцией чернил")
                openRouterEngine = it
            }
        }
        EngineType.GOOGLE -> {
            googleAiEngine ?: GoogleAiOcrEngine(context, ocrPreferences).also {
                googleAiEngine = it
            }
        }
        EngineType.ZEN_FREE -> {
            zenFreeEngine ?: ZenFreeOcrEngine().also {
                zenFreeEngine = it
            }
        }
    }
}

private fun detectionEngine(): DetOcrEngine {
    return detEngine ?: (
        // Детектор живёт в паке cyrillic_ocr вместе с распознавателями.
        // Пока модели не скачаны (или LiteRT недоступен) — заглушка, и
        // scanLocally честно деградирует на распознавание всей страницы.
        if (localOcrAvailable() && cyrillicModelsInstalled()) {
            CyrillicDetOcrEngine { engineFor(EngineType.CYRILLIC) as CyrillicOcrEngine }
        } else {
            UnavailableDetOcrEngine()
        }
        ).also {
        detEngine = it
    }
}

/** Пак cyrillic_ocr установлен целиком (детектор + распознаватель + словарь). */
private fun cyrillicModelsInstalled(): Boolean {
    return OcrModelFiles.allInstalled(
        context,
        listOf(
            CyrillicOcrEngine.DETECTOR_PATH,
            CyrillicOcrEngine.PRIMARY_PATH,
            CyrillicOcrEngine.PRIMARY_DICT_PATH,
        ),
    )
