if (viewer is R2LPagerViewer && placeAtIndex - 1 >= 0 && items[placeAtIndex - 1] is InsertPage) {
    return
}

// Same here it will enter a endless cycle of insert pages
if (placeAtIndex < items.size && items[placeAtIndex] is InsertPage) {
    return
