/**
 * Implementation of a [Viewer] to display pages with a [RecyclerView].
 */
class WebtoonViewer(val activity: ReaderActivity, val isContinuous: Boolean = true) : Viewer {

    val downloadManager: DownloadManager by injectLazy()

    private val scope = MainScope()

    /**
     * Recycler view used by this viewer.
     */
    val recycler = WebtoonRecyclerView(activity)

    /**
     * Frame containing the recycler view.
     */
    private val frame = WebtoonFrame(activity)

    /**
     * Distance to scroll when the user taps on one side of the recycler view.
     */
    private val scrollDistance = activity.resources.displayMetrics.heightPixels * 3 / 4

    /**
     * Layout manager of the recycler view.
     */
    private val layoutManager = WebtoonLayoutManager(activity, scrollDistance)

    /**
     * Configuration used by this viewer, like allow taps, or crop image borders.
     */
    val config = WebtoonConfig(scope)

    /**
     * Adapter of the recycler view.
     */
    private val adapter = WebtoonAdapter(this)

    /**
     * Currently active item. It can be a chapter page or a chapter transition.
     */
    private var currentPage: Any? = null

    private val threshold: Int =
        Injekt.get<ReaderPreferences>()
            .readerHideThreshold
            .get()
            .threshold

    init {
        recycler.setItemViewCacheSize(RECYCLER_VIEW_CACHE_SIZE)
        recycler.isVisible = false // Don't let the recycler layout yet
        recycler.layoutParams = ViewGroup.LayoutParams(MATCH_PARENT, MATCH_PARENT)
        recycler.isFocusable = false
        recycler.itemAnimator = null
        recycler.layoutManager = layoutManager
        recycler.adapter = adapter
        recycler.addOnScrollListener(
            object : RecyclerView.OnScrollListener() {
                override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {
                    onScrolled()

                    if ((dy > threshold || dy < -threshold) && activity.viewModel.state.value.menuVisible) {
                        activity.hideMenu()
                    }

                    if (dy < 0) {
                        val firstIndex = layoutManager.findFirstVisibleItemPosition()
                        val firstItem = adapter.items.getOrNull(firstIndex)
                        if (firstItem is ChapterTransition.Prev && firstItem.to != null) {
                            activity.requestPreloadChapter(firstItem.to)
                        }
                    }

                    val lastIndex = layoutManager.findLastEndVisibleItemPosition()
                    val lastItem = adapter.items.getOrNull(lastIndex)
                    if (lastItem is ChapterTransition.Next && lastItem.to == null) {
                        activity.showMenu()
                    }
                }
            },
        )
        recycler.tapListener = tap@{ event ->
            val child = recycler.findChildViewUnder(event.x, event.y) as? ReaderPageImageView
            val activeOverlayTap = if (activity.hasActiveOcrOverlaySession()) {
                child?.let {
                    // Webtoon can be scaled/translated; use recycler-local coordinates for stable hit-testing.
                    val localX = event.x - it.x
                    val localY = event.y - it.y
                    it.tryConsumeActiveOcrOverlayTapLocal(localX, localY)
                }
            } else {
                null
            }
            when (activeOverlayTap) {
                is ReaderActiveOcrTapResult.SelectWord -> {
                    activity.searchActiveOcrOverlay(activeOverlayTap.offset)
                    return@tap
                }
                ReaderActiveOcrTapResult.BubbleTap -> {
                    activity.dismissActiveOcrOverlaySession()
                    return@tap
                }
                null -> {}
            }

            val consumedOcrTap = if (activity.shouldHandleCachedOcrRegionTaps()) {
                child?.let {
                    val localX = event.x - it.x
                    val localY = event.y - it.y
                    it.tryConsumeOcrTapLocal(localX, localY)
                } == true
            } else {
                false
            }
            if (!consumedOcrTap) {
                if (activity.hasActiveOcrOverlaySession()) {
                    activity.dismissActiveOcrOverlaySession()
                    return@tap
                }

                val viewPosition = IntArray(2)
                recycler.getLocationOnScreen(viewPosition)
                val viewPositionRelativeToWindow = IntArray(2)
                recycler.getLocationInWindow(viewPositionRelativeToWindow)
                val pos = PointF(
                    (event.rawX - viewPosition[0] + viewPositionRelativeToWindow[0]) / recycler.width,
                    (event.rawY - viewPosition[1] + viewPositionRelativeToWindow[1]) / recycler.originalHeight,
                )
                when (config.navigator.getAction(pos)) {
                    NavigationRegion.MENU -> activity.toggleMenu()
                    NavigationRegion.NEXT, NavigationRegion.RIGHT -> scrollDown()
                    NavigationRegion.PREV, NavigationRegion.LEFT -> scrollUp()
                }
            }
        }
        recycler.longTapListener = f@{ event ->
            if (activity.viewModel.state.value.menuVisible || config.longTapEnabled) {
                val child = recycler.findChildViewUnder(event.x, event.y)
                if (child != null) {
                    val position = recycler.getChildAdapterPosition(child)
                    val item = adapter.items.getOrNull(position)
                    if (item is ReaderPage) {
                        if (config.longTapOcr) {
                            activity.enterOcrMode()
                        } else {
                            activity.onPageLongTap(item)
                        }
                        return@f true
                    }
                }
            }
            false
        }

        config.imagePropertyChangedListener = {
            refreshAdapter()
        }

        config.themeChangedListener = {
            ActivityCompat.recreate(activity)
        }

        config.doubleTapZoomChangedListener = {
            frame.doubleTapZoom = it
        }

        config.zoomPropertyChangedListener = {
            frame.zoomOutDisabled = it
        }

        config.navigationModeChangedListener = {
            val showOnStart = config.navigationOverlayOnStart || config.forceNavigationOverlay
            activity.binding.navigationOverlay.setNavigation(config.navigator, showOnStart)
        }

        frame.layoutParams = ViewGroup.LayoutParams(MATCH_PARENT, MATCH_PARENT)
        frame.addView(recycler)
    }

    private fun checkAllowPreload(page: ReaderPage?): Boolean {
        // Page is transition page - preload allowed
        page ?: return true

        // Initial opening - preload allowed
        currentPage ?: return true

        val nextItem = adapter.items.getOrNull(adapter.items.size - 1)
        val nextChapter = (nextItem as? ChapterTransition.Next)?.to ?: (nextItem as? ReaderPage)?.chapter

        // Allow preload for
        // 1. Going between pages of same chapter
        // 2. Next chapter page
        return when (page.chapter) {
            (currentPage as? ReaderPage)?.chapter -> true
            nextChapter -> true
            else -> false
        }
    }

    /**
     * Returns the view this viewer uses.
     */
    override fun getView(): View {
        return frame
    }

    override fun setActiveOcrOverlay(overlay: ReaderActiveOcrOverlay?): Boolean {
        var matched = overlay == null
        recycler.children
            .filterIsInstance(ReaderPageImageView::class.java)
            .forEach { pageView ->
                val activeOverlay = overlay?.takeIf { pageView.matchesOcrPage(it.page) }
                pageView.setActiveOcrOverlay(activeOverlay)
                if (activeOverlay != null) {
                    matched = true
                }
            }
        return matched
    }

    override fun displayedPageRect(): android.graphics.RectF? {
        val height = frame.height.toFloat()
        val width = frame.width.toFloat()
        if (width <= 0f || height <= 0f) return null

        // В ленте одновременно видно несколько страниц: берём ту, что
        // пересекает центр экрана — именно её сейчас читают.
        val centerY = height / 2f
        val pageView = recycler.children
            .filterIsInstance(ReaderPageImageView::class.java)
            .firstOrNull { child ->
                val top = child.y + recycler.y
                top <= centerY && centerY <= top + child.height
            } ?: return null

        val imageRect = pageView.displayedImageRectOrNull() ?: return null
        val offsetX = pageView.x + recycler.x
        val offsetY = pageView.y + recycler.y

        return android.graphics.RectF(
            (imageRect.left + offsetX) / width,
            (imageRect.top + offsetY) / height,
            (imageRect.right + offsetX) / width,
            (imageRect.bottom + offsetY) / height,
        )
    }

    override fun resolveSelectionCaptures(region: ReaderSelectionRegion): List<ReaderSelectionCapture> {
        return recycler.children
            .filterIsInstance(ReaderPageImageView::class.java)
            .mapNotNull { child ->
                val childRect = android.graphics.Rect()
                if (!child.getGlobalVisibleRect(childRect)) return@mapNotNull null

                val intersection = android.graphics.RectF(region.screenRect)
                if (!intersection.intersect(android.graphics.RectF(childRect))) return@mapNotNull null

                val page = adapter.items
                    .getOrNull(recycler.getChildAdapterPosition(child)) as? ReaderPage
                    ?: return@mapNotNull null
                val chapterId = page.chapter.chapter.id ?: return@mapNotNull null
                val pageIdentity = ReaderOcrPageIdentity(chapterId, page.index)
                if (!child.matchesOcrPage(pageIdentity)) return@mapNotNull null

                val sourceRect = child.sourceRectForScreenRect(intersection) ?: return@mapNotNull null
                ReaderSelectionCapture(
                    page = page,
                    sourceRect = sourceRect,
                    screenRect = intersection,
                    bitmapSource = child,
                )
            }
            .toList()
            .sortedWith(compareBy<ReaderSelectionCapture> { it.screenRect.top }.thenBy { it.screenRect.left })
    }

    /**
     * Destroys this viewer. Called when leaving the reader or swapping viewers.
     */
    override fun destroy() {
        super.destroy()
        scope.cancel()
    }

    /**
     * Called from the RecyclerView listener when a [page] is marked as active. It notifies the
     * activity of the change and requests the preload of the next chapter if this is the last page.
     */
    private fun onPageSelected(page: ReaderPage, allowPreload: Boolean) {
        val pages = page.chapter.pages ?: return
        logcat { "onPageSelected: ${page.number}/${pages.size}" }
        activity.onPageSelected(page)

        // Preload next chapter once we're within the last 5 pages of the current chapter
        val inPreloadRange = pages.size - page.number < 5
        if (inPreloadRange && allowPreload && page.chapter == adapter.currentChapter) {
            logcat { "Request preload next chapter because we're at page ${page.number} of ${pages.size}" }
            val nextItem = adapter.items.getOrNull(adapter.items.size - 1)
            val transitionChapter = (nextItem as? ChapterTransition.Next)?.to ?: (nextItem as?ReaderPage)?.chapter
            if (transitionChapter != null) {
                logcat { "Requesting to preload chapter ${transitionChapter.chapter.chapter_number}" }
                activity.requestPreloadChapter(transitionChapter)
            }
        }

        activity.syncActiveOcrOverlay()
    }

    /**
     * Called from the RecyclerView listener when a [transition] is marked as active. It request the
     * preload of the destination chapter of the transition.
     */
    private fun onTransitionSelected(transition: ChapterTransition) {
        logcat { "onTransitionSelected: $transition" }
        activity.dismissActiveOcrOverlaySession()
        val toChapter = transition.to
        if (toChapter != null) {
            logcat { "Request preload destination chapter because we're on the transition" }
            activity.requestPreloadChapter(toChapter)
        }
    }

    /**
     * Tells this viewer to set the given [chapters] as active.
     */
    override fun setChapters(chapters: ViewerChapters) {
        val forceTransition = config.alwaysShowChapterTransition || currentPage is ChapterTransition
        adapter.setChapters(chapters, forceTransition)

        if (recycler.isGone) {
            logcat { "Recycler first layout" }
            val pages = chapters.currChapter.pages ?: return
            moveToPage(pages[min(chapters.currChapter.requestedPage, pages.lastIndex)])
            recycler.isVisible = true
        }
    }

    /**
     * Tells this viewer to move to the given [page].
     */
    override fun moveToPage(page: ReaderPage) {
        val position = adapter.items.indexOf(page)
        if (position != -1) {
            layoutManager.scrollToPositionWithOffset(position, 0)
            if (layoutManager.findLastEndVisibleItemPosition() == -1) {
                onScrolled(pos = position)
            }
        } else {
            logcat { "Page $page not found in adapter" }
        }
    }

    fun onScrolled(pos: Int? = null) {
        val position = pos ?: layoutManager.findLastEndVisibleItemPosition()
        val item = adapter.items.getOrNull(position)
        val allowPreload = checkAllowPreload(item as? ReaderPage)
        if (item != null && currentPage != item) {
            currentPage = item
            when (item) {
                is ReaderPage -> onPageSelected(item, allowPreload)
                is ChapterTransition -> onTransitionSelected(item)
            }
        }
    }

    /**
     * Scrolls up by [scrollDistance].
     */
    private fun scrollUp() {
        if (config.usePageTransitions) {
            recycler.smoothScrollBy(0, -scrollDistance)
        } else {
            recycler.scrollBy(0, -scrollDistance)
        }
    }

    /**
     * Scrolls down by [scrollDistance].
     */
    fun scrollDown() {
        if (config.usePageTransitions) {
            recycler.smoothScrollBy(0, scrollDistance)
        } else {
            recycler.scrollBy(0, scrollDistance)
        }
    }

    /**
     * Плавный прокрут на долю высоты экрана. Нужен авточтения: штатный
     * [scrollDown] листает на 3/4 экрана, из-за чего нижние реплики кадра
     * выпадали и «читались» снова только рывком. Меньший шаг (с перекрытием)
     * держит автопрокрутку, пока кадр не прочитан, и не пропускает текст на
     * границе вьюпорта.
     */
    fun scrollDownByFraction(fraction: Float) {
        val px = (activity.resources.displayMetrics.heightPixels * fraction)
            .toInt()
            .coerceAtLeast(1)
        if (config.usePageTransitions) {
            recycler.smoothScrollBy(0, px)
        } else {
            recycler.scrollBy(0, px)
        }
    }

    /**
     * Called from the containing activity when a key [event] is received. It should return true
     * if the event was handled, false otherwise.
     */
    override fun handleKeyEvent(event: KeyEvent): Boolean {
        val isUp = event.action == KeyEvent.ACTION_UP

        when (event.keyCode) {
            KeyEvent.KEYCODE_VOLUME_DOWN -> {
                if (!config.volumeKeysEnabled || activity.viewModel.state.value.menuVisible) {
                    return false
                } else if (isUp) {
                    if (!config.volumeKeysInverted) scrollDown() else scrollUp()
                }
            }
            KeyEvent.KEYCODE_VOLUME_UP -> {
                if (!config.volumeKeysEnabled || activity.viewModel.state.value.menuVisible) {
                    return false
                } else if (isUp) {
                    if (!config.volumeKeysInverted) scrollUp() else scrollDown()
                }
            }
            KeyEvent.KEYCODE_MENU -> if (isUp) activity.toggleMenu()

            KeyEvent.KEYCODE_DPAD_LEFT,
            KeyEvent.KEYCODE_DPAD_UP,
            KeyEvent.KEYCODE_PAGE_UP,
            -> if (isUp) scrollUp()

            KeyEvent.KEYCODE_DPAD_RIGHT,
            KeyEvent.KEYCODE_DPAD_DOWN,
            KeyEvent.KEYCODE_PAGE_DOWN,
            -> if (isUp) scrollDown()
            else -> return false
        }
        return true
    }

    /**
     * Called from the containing activity when a generic motion [event] is received. It should
     * return true if the event was handled, false otherwise.
     */
    override fun handleGenericMotionEvent(event: MotionEvent): Boolean {
        return false
    }

    /**
     * Notifies adapter of changes around the current page to trigger a relayout in the recycler.
     * Used when an image configuration is changed.
     */
    private fun refreshAdapter() {
        val position = layoutManager.findLastEndVisibleItemPosition()
        adapter.refresh()
        adapter.notifyItemRangeChanged(
            max(0, position - 3),
            min(position + 3, adapter.itemCount - 1),
        )
    }
}

// Double the cache size to reduce rebinds/recycles incurred by the extra layout space on scroll direction changes
private const val RECYCLER_VIEW_CACHE_SIZE = 4

package eu.kanade.tachiyomi.ui.reader.viewer.webtoon

import android.content.res.Resources
import android.view.LayoutInflater
import android.view.ViewGroup
