        val context = LocalContext.current
        val prefs = remember { Injekt.get<OcrPreferences>() }
        val pat by prefs.githubPat().changes().collectAsState(initial = prefs.githubPat().get())
        val starting by hubStartingFlow.collectAsState()
        val status by hubStatusFlow.collectAsState()
        val session by hubSessionFlow.collectAsState()
        var sessions by remember {
            mutableStateOf(runCatching { RunnerLlm.listSessions(context) }.getOrDefault(emptyList()))
        }
        // Лента событий ранера: последние прогоны и пошаговая лента задач.
        // Читатель просил видеть, что ранер делал, не выспрашивая агента.
        var events by remember { mutableStateOf<List<AiGithub.Run>>(emptyList()) }
        var eventsLoading by remember { mutableStateOf(false) }
        var eventsError by remember { mutableStateOf("") }

        val loadEvents: () -> Unit = {
            if (pat.isBlank()) {
                eventsError = "Сначала вставьте GitHub PAT"
            } else {
                eventsLoading = true
                eventsError = ""
                val token = pat.trim()
                chatScope.launch {
                    val got = runCatching { AiGithub.runs(token, AiGithub.DEFAULT_REPO, perPage = 8) }
                        .getOrElse { emptyList() }
                    withContext(Dispatchers.Main) {
                        events = got
                        eventsLoading = false
                        if (got.isEmpty() && eventsError.isBlank()) {
                            eventsError = "Прогонов не найдено или сеть недоступна"
                        }
                    }
                }
            }
        }

        val openSession = session
        if (openSession != null) {
            HubWebView(
                session = openSession,
                onClose = { hubSessionFlow.value = null },
            )
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .statusBarsPadding()
                    .imePadding()
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                Text("OpenCode-агент", style = MaterialTheme.typography.titleMedium)
                Text(
                    "Запускает сайт-хаб (npm-hub) на GitHub-ранере: дашборд, терминал, " +
                        "файлы, git, инструменты. Нужного CLI-агента (opencode, DeepSeek, UTIM, " +
                        "AI Shell и др.) вы сами выбираете и устанавливаете прямо внутри хаба. " +
                        "Ранер работает вашим PAT аккаунта, поэтому видит и меняет ВСЕ репозитории " +
                        "аккаунта. Нужен PAT с правом actions:write.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                OutlinedTextField(
                    value = pat,
                    onValueChange = { token ->
                        // Пробелы по краям ломают GitHub Auth: token = " ghp_…x "
                    // считается невалидным и старт сессии падает с 401.
                        prefs.githubPat().set(token.trim())
                    },
                    label = { Text("GitHub PAT") },
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 1,
                )
                var elapsed by remember { mutableStateOf(0L) }
                LaunchedEffect(starting) {
                    elapsed = 0
                    while (starting) {
                        delay(1000)
                        elapsed++
                    }
                }
                FilledTonalButton(
                    enabled = !starting && pat.isNotBlank(),
                    onClick = {
                        val trimmed = pat.trim()
                        val looksLikePat = trimmed.startsWith("ghp_") ||
                            trimmed.startsWith("github_pat_") ||
                            trimmed.startsWith("gho_") ||
                            trimmed.startsWith("ghs_") ||
                            trimmed.startsWith("ghr_")
                        if (!looksLikePat) {
                            hubStatusFlow.value =
                                "❌ Токен не похож на GitHub PAT. Нужен токен, " +
                                "начинающийся на ghp_ / github_pat_ / gho_ (Settings → Developer settings → " +
                                "Personal access tokens). Вставлен Discord- или другой токен?"
                            return@FilledTonalButton
                        }
                        hubStartingFlow.value = true
                        hubStatusFlow.value = "⏳ Запуск хаба npm-hub…"
                        val appCtx = context.applicationContext
                        chatScope.launch {
                            val s = runCatching {
                                RunnerLlm.startOpenCode(
                                    appCtx,
                                    { st -> hubStatusFlow.value = st },
                                    os = "linux",
                                    ui = "mobile",
                                )
                            }.getOrElse {
                                hubStatusFlow.value = "❌ Ошибка запуска: ${it.message ?: it}"
                                null
                            }
                            withContext(Dispatchers.Main) {
                                hubStartingFlow.value = false
                                if (s != null) {
                                    sessions = runCatching { RunnerLlm.listSessions(context) }
                                        .getOrDefault(emptyList())
                                    rememberSession(s)
                                }
                            }
                        }
                    },
                ) { Text(if (starting) "Запускаем…" else "▶ Запустить") }
                if (status.isNotBlank()) {
                    Text(
                        if (starting) "$status • ${elapsed / 60}:${"%02d".format(elapsed % 60)}"
                        else status,
                        style = MaterialTheme.typography.bodySmall,
                    )
                }
                // Лента событий ранера. Раньше читатель видел только «сессии»
                // и кнопку «Открыть»: что ранер делал внутри прогона, не было
                // видно нигде, хотя GitHub Actions это знает.
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    FilterChip(
                        selected = events.isNotEmpty(),
                        onClick = { loadEvents() },
                        label = { Text("События ранера") },
                    )
                    if (eventsLoading) {
                        Text("Загрузка…", style = MaterialTheme.typography.labelSmall)
                    }
                }
                if (eventsError.isNotBlank()) {
                    Text(
                        eventsError,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
                events.forEach { r ->
                    var steps by remember(r.id) { mutableStateOf<String?>(null) }
                    var stepsLoading by remember(r.id) { mutableStateOf(false) }
                    Column(modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp)) {
                        Text(
                            "#${r.id} ${r.name} — ${r.stateRu}",
                            style = MaterialTheme.typography.bodySmall,
                        )
                        Text(
                            "Показать шаги",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.clickable {
                                if (steps != null || stepsLoading) return@clickable
                                stepsLoading = true
                                val token = pat.trim()
                                val runId = r.id
                                chatScope.launch {
                                    val text = runCatching {
                                        AiGithub.renderJobs(AiGithub.jobs(token, runId))
                                    }.getOrElse { "Не удалось прочитать шаги: ${it.message}" }
                                    withContext(Dispatchers.Main) {
                                        steps = text
                                        stepsLoading = false
                                    }
                                }
                            },
                        )
                        if (stepsLoading) {
                            Text("…", style = MaterialTheme.typography.labelSmall)
                        }
                        steps?.let { txt ->
                            Text(
                                txt,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                            )
                        }
                    }
                }
                if (sessions.isNotEmpty()) {
                    Text("Сессии:", style = MaterialTheme.typography.bodySmall)
                    sessions.forEach { s ->
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            Text(
                                "${s.model} • ${s.messages.size} сообщ. • ${s.os}",
                                style = MaterialTheme.typography.bodySmall,
                                modifier = Modifier.weight(1f),
                            )
                            if (s.terminalUrl != null || s.url != null) {
                                FilterChip(
                                    selected = false,
                                    onClick = { rememberSession(s) },
                                    label = { Text("Открыть") },
                                )
                            }
                            FilterChip(
                                selected = false,
                                onClick = {
                                    runCatching {
                                        RunnerLlm.deleteSession(context, s)
                                        sessions = RunnerLlm.listSessions(context)
                                    }
                                },
                                label = { Text("✕") },
                            )
                        }
                    }
                }
            }
        }
    }

    /** Сайт-хаб npm-hub в той же вкладке: loading-экран вместо чёрного + ошибки. */
    @Composable
    @android.annotation.SuppressLint("SetJavaScriptEnabled")
    private fun HubWebView(
        session: RunnerLlm.Session,
        onClose: () -> Unit,
    ) {
        val context = LocalContext.current
        val url = session.terminalUrl ?: session.url.orEmpty()
        var loading by remember(session.id) { mutableStateOf(true) }
        var error by remember(session.id) { mutableStateOf<String?>(null) }
        val webView = remember(session.id, url) {
            runCatching {
                WebView(context).apply {
                    // На чёрном фоне «протухающий» туннель выглядел как мёртвый экран.
                    setBackgroundColor(android.graphics.Color.WHITE)
                    isFocusable = true
                    isFocusableInTouchMode = true
                    settings.javaScriptEnabled = true
                    settings.domStorageEnabled = true
                    settings.loadWithOverviewMode = false
                    settings.useWideViewPort = false
                    settings.builtInZoomControls = false
                    settings.displayZoomControls = false
                    settings.mixedContentMode = android.webkit.WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
                    webViewClient = object : WebViewClient() {
                        override fun onReceivedHttpAuthRequest(
                            view: WebView?,
                            handler: HttpAuthHandler,
                            host: String?,
                            realm: String?,
                        ) {
                            runCatching { handler.proceed("yomikai", session.apiKey.orEmpty()) }
                        }

                        override fun onPageFinished(view: WebView?, url: String?) {
                            loading = false
                            error = null
                            view?.requestFocus()
                        }

                        override fun onReceivedError(
                            view: WebView?,
                            errorCode: Int,
                            description: String?,
                            failingUrl: String?,
                        ) {
                            loading = false
                            error = "Ошибка загрузки ($errorCode): $description"
                        }

                        override fun onReceivedHttpError(
                            view: WebView?,
                            request: android.webkit.WebResourceRequest?,
                            errorResponse: android.webkit.WebResourceResponse?,
                        ) {
                            loading = false
                            val code = errorResponse?.statusCode ?: 0
                            val mime = errorResponse?.mimeType.orEmpty()
                            // Discord api error format leaked through a proxy/token:
                            // {"success":false,"result":null,"errors":[{"code":10005,...}]}
                            val body = runCatching {
                                errorResponse?.data?.bufferedReader()?.use { it.readText() }.orEmpty()
                            }.getOrDefault("").take(300)
                            if (code == 405 || body.contains("method not allowed", ignoreCase = true)) {
                                error = "Ранер ответил $code (Method Not Allowed). Скорее всего в поле " +
                                    "GitHub PAT вставлен НЕ-GitHub токен (например Discord). Возьмите " +
                                    "настоящий GitHub PAT (ghp_/github_pat_). Ответ: $body"
                            } else {
                                error = "HTTP $code на сайте ранера" +
                                    body.takeIf { it.isNotBlank() }?.let { "\n$it" }.orEmpty()
                            }
                        }
                    }
                    if (url.isNotBlank()) loadUrl(url)
                }
            }.getOrElse {
                error = "WebView не создался: ${it.message ?: it}"
                null
            }
        }
        DisposableEffect(webView) {
            onDispose {
                runCatching {
                    (webView?.parent as? android.view.ViewGroup)?.removeView(webView)
                    webView?.stopLoading()
                    webView?.destroy()
                }
            }
        }

        Column(modifier = Modifier.fillMaxSize().statusBarsPadding()) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Text(
                    "npm-hub • ${session.os}" +
                        (if (loading) " • подключение…" else " • сайт"),
                    style = MaterialTheme.typography.bodySmall,
                    modifier = Modifier.weight(1f),
                )
                IconButton(onClick = {
                    loading = true
                    error = null
                    runCatching { webView?.reload() }
                }) {
                    Icon(Icons.Outlined.Refresh, contentDescription = "Перезагрузить")
                }
                TextButton(onClick = onClose) { Text("Закрыть") }
            }
            if (webView != null && error == null) {
                AndroidView(
                    factory = { webView },
                    modifier = Modifier.fillMaxSize(),
                )
            } else {
                Column(
                    modifier = Modifier.fillMaxSize().padding(24.dp),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(
                        error ?: "Сайт хаба недоступен. Проверьте, что ранер ещё жив.",
                        style = MaterialTheme.typography.bodyMedium,
                    )
                    FilledTonalButton(
                        onClick = { error = null; loading = true; runCatching { webView?.reload() } },
                    ) { Text("Попробовать снова") }
                    TextButton(onClick = onClose) { Text("Закрыть и к запуску") }
                }
            }
        }
    }
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import eu.kanade.tachiyomi.data.tts.EdgeTts
import eu.kanade.tachiyomi.data.tts.TtsSpeaker
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.File

/**
 * Инструменты AI-чата: генерация звука и работа с голосами озвучки.
 *
 * Тот же принцип, что у [AiReaderTools]: инструменты читают те же настройки,
 * которые видит пользователь (голос — `OcrPreferences.edgeVoice`), а файлы
 * создаются внутри workspace (`audio/`), поэтому результат сразу появляется
 * в чате чипом файла с размером и кнопкой «Отправить».
 */
object AiChatTools {

    const val TOOL_RENDER_AUDIO = "render_audio"
    const val TOOL_VOICE_LIST = "voice_list"
    const val TOOL_VOICE_PREVIEW = "voice_preview"
    const val TOOL_VOICE_SET = "voice_set"
    const val TOOL_GEN_VIDEO = "gen_video"

    val TOOL_NAMES = listOf(
        TOOL_RENDER_AUDIO,
        TOOL_VOICE_LIST,
        TOOL_VOICE_PREVIEW,
        TOOL_VOICE_SET,
        TOOL_GEN_VIDEO,
    )

    /** Документация инструментов для системного промпта агента. */
    val SYSTEM_PROMPT_LINES = listOf(
        "@tool render_audio {\"text\":\"текст\",\"voice\":\"ru-RU-SvetlanaNeural\",\"name\":\"имя.mp3\"} — озвучить ТЕКСТ голосом в файл MP3 (workspace/audio/), файл появится в чате готовым. ВАЖНО: он берёт только текст, страницу книги им прочитать нельзя — за «прочти книгу/страницу и пришли аудиофайл» отвечают действия читалки reader_do {\"action\":\"page_audio\"} и {\"action\":\"chapter_audio\"}: они распознают страницу тем же OCR и синтезируют mp3 в workspace/audio/, файл приходит карточкой в чат. Не подменяй их render_audio и уж тем более авточтением",
        "@tool voice_list {} — список голосов Edge TTS и какой сейчас выбран",
        "@tool voice_preview {\"voice\":\"ru-RU-DmitryNeural\"} — проиграть пробу голоса, чтобы пользователь послушал",
        "@tool voice_set {\"voice\":\"ru-RU-DmitryNeural\"} — сменить голос озвучки приложения на указанный",
        "@tool gen_video {\"text\":\"заголовок\",\"images\":[\"https://image.pollinations.ai/prompt/a%20cat\"],\"fps\":3,\"name\":\"видео.mp4\"} — собрать видео на GitHub-ранере (нужен PAT-токен в настройках вкладки AI): slideshow из images или текстовая анимация; файл появится в чате готовым",
    )

    /** Короткий каталог голосов Edge TTS для `voice_list` (без сети). */
    private val edgeCatalog = listOf(
        "ru-RU-SvetlanaNeural (рус, жен., тёплый)",
        "ru-RU-DmitryNeural (рус, муж.)",
        "ru-RU-DariyaNeural (рус, жен., спокойный)",
        "ru-RU-PavelNeural (рус, муж., спокойный)",
        "ru-RU-ElinaNeural (рус, жен.)",
        "ru-RU-DenisNeural (рус, муж.)",
        "ru-RU-IrinaNeural (рус, жен., повествование)",
        "ru-RU-MaximNeural (рус, муж., повествование)",
        "uk-UA-PolinaNeural (укр, жен.)",
        "uk-UA-OstapNeural (укр, муж.)",
        "en-US-JennyNeural (англ, жен.)",
        "en-US-GuyNeural (англ, муж.)",
    )

    private const val DEFAULT_VOICE = "ru-RU-SvetlanaNeural"

    data class RenderOutcome(val output: String, val file: File? = null)

    private fun prefs(): OcrPreferences = Injekt.get()

    /** Что озвучивается сейчас и какие голоса можно попробовать. */
    fun voiceList(context: Context): String {
        val current = prefs().edgeVoice().get().ifBlank { DEFAULT_VOICE }
        return buildString {
            appendLine("Текущий голос озвучки (Edge): «$current»")
            appendLine()
            appendLine("Каталог голосов Edge TTS:")
            edgeCatalog.forEach { appendLine("• $it") }
            append("Проба: voice_preview {\"voice\":\"имя\"}; смена: voice_set {\"voice\":\"имя\"}")
        }
    }

    /** Проиграть пробу голоса прямо сейчас (файл не создаётся). */
    fun previewVoice(context: Context, voice: String?): String {
        val v = voice?.takeIf { it.isNotBlank() } ?: prefs().edgeVoice().get().ifBlank { DEFAULT_VOICE }
        TtsSpeaker.speakEdgeVoiceTest(context, v)
        return "Играет проба голоса «$v»: «Привет! Это тест голоса $v.»"
    }

    /** Запомнить выбранный голос в настройках озвучки. */
    fun voiceSet(voice: String): String {
        val v = voice.trim()
        when {
            v.isEmpty() -> return "ОШИБКА: пустое имя голоса (пример: ru-RU-DmitryNeural)"
            !v.contains("-") -> return "ОШИБКА: имя голоса должно содержать дефис (пример: ru-RU-DmitryNeural)"
            else -> {
                prefs().edgeVoice().set(v)
                return "Голос озвучки сменён на «$v». Проверка: voice_preview {\"voice\":\"$v\"}, статус: tts_status"
            }
        }
    }

    /** Озвучить текст в MP3-файл внутри workspace (`audio/`). Телефон сам не играет. */
    suspend fun renderAudio(
        context: Context,
        text: String,
        voice: String?,
        nameHint: String?,
    ): RenderOutcome = withContext(Dispatchers.IO) {
        val clean = text.trim()
        if (clean.isEmpty()) {
            return@withContext RenderOutcome("ОШИБКА: пустой text")
        }
        val v = voice?.takeIf { it.isNotBlank() } ?: prefs().edgeVoice().get().ifBlank { DEFAULT_VOICE }
        val synthesized = EdgeTts.synthesizeToFile(context, clean, v, useCache = false)
        if (synthesized == null) {
            return@withContext RenderOutcome("ОШИБКА: синтез не удался (нет сети или сервер Edge не ответил)")
        }
        if (synthesized.length() < 1024) {
            return@withContext RenderOutcome("ОШИБКА: файл получился пустым — проверьте текст и голос")
        }
        val base = (nameHint ?: "voice_${System.currentTimeMillis() / 1000}").let(::sanitizeName)
        val mp3 = if (base.endsWith(".mp3", true)) base else "$base.mp3"
        val dest = AiWorkspace.resolve(context, "audio/$mp3")
        if (dest == null) {
            return@withContext RenderOutcome("ОШИБКА: некорректное имя файла: $nameHint")
        }
        runCatching {
            dest.parentFile?.mkdirs()
            synthesized.copyTo(dest, overwrite = true)
        }.onFailure {
            return@withContext RenderOutcome("ОШИБКА: не удалось записать файл: ${it.message?.take(100)}")
        }
        RenderOutcome("Аудио готово: audio/$mp3 (${dest.length() / 1024} КБ, голос «$v»)", dest)
    }

    /**
     * Собрать видео на GitHub-ранере (video-runner.yml, нужен PAT-токен):
     * текстовая анимация или слайд-шоу из [images]-URL. Готовый mp4 кладётся
     * в workspace (`videos/`) и появляется в чате готовым.
     */
    suspend fun renderVideo(
        context: Context,
        images: List<String>,
        text: String,
        fps: Int,
        nameHint: String?,
        onStatus: (String) -> Unit = {},
    ): RenderOutcome = withContext(Dispatchers.IO) {
        val result = RunnerLlm.startVideo(
            context,
            RunnerLlm.VideoRequest(
                mode = if (images.isNotEmpty()) "slideshow" else "text",
                text = text,
                images = images,
                fps = fps,
            ),
            onStatus,
        )
        if (result == null) {
            return@withContext RenderOutcome("ОШИБКА: видео не создано — нужен GitHub-токен (⚙ вкладки AI) или сеть не дала связаться с ранером")
        }
        val base = (nameHint ?: "video_${System.currentTimeMillis() / 1000}").let(::sanitizeName)
        val mp4name = if (base.endsWith(".mp4", true)) base else "$base.mp4"
        val dest = AiWorkspace.resolve(context, "videos/$mp4name")
        if (dest == null) {
            return@withContext RenderOutcome("ОШИБКА: некорректное имя файла: $nameHint")
        }
        runCatching {
            dest.parentFile?.mkdirs()
            result.file.copyTo(dest, overwrite = true)
        }.onFailure {
            return@withContext RenderOutcome("ОШИБКА: не удалось записать файл: ${it.message?.take(100)}")
        }
        RenderOutcome("Видео готово: videos/$mp4name (${dest.length() / 1024} КБ)", dest)
    }

    /** Только безопасные для файловой системы символы. */
    private fun sanitizeName(name: String): String =
        name.replace(Regex("[\\\\/:*?\"<>|\\s]+"), "_")
            .replace(Regex("[^A-Za-zА-Яа-яЁё0-9._-]"), "_")
            .trim('_', '.')
            .take(64)
            .ifBlank { "voice_${System.currentTimeMillis() / 1000}" }
}

package eu.kanade.tachiyomi.data.ai

/**
 * Как ассистент работает с ЭТОЙ книгой: три настройки, которые читатель
 * переключает прямо в чате читалки.
 *
 *  * [MODE_CHAT] — обычный помощник: отвечает по книге, ищет источники, ведёт
 *    дела. То, что было по умолчанию.
 *  * [MODE_ROLEPLAY] — «дружеская встреча»: ассистент отыгрывает героев и
 *    общается вместо справочного тона. Знания книги при этом не теряются —
 *    режим меняет тон, а не память.
 *  * [MATURE_ALLOWED] — для книг 18+ ассистент может обсуждать зрелые темы.
 *    Для остальных книг запрет остаётся жёстким.
 *  * [CENSORSHIP_ON] — фильтр грубых слов в ответе. Это косметика для
 *    спокойного чтения, а не фильтр содержания: грубые слова маскируются
 *    звёздочками, смысл ответа не меняется.
 *
 * Жёсткая граница, которую нельзя переключить: никакого сексуального
 * контента с несовершеннолетними, никаких отыгрышей реальных людей и
 * никакого сексуального насилия. Это не настройка, а правило ассистента.
 */
object BookChatProfile {

    const val MODE_CHAT = "chat"
    const val MODE_ROLEPLAY = "roleplay"

    const val MODE_CHAT_TITLE = "Чат"
    const val MODE_ROLEPLAY_TITLE = "Отыгрыш"

    val MODES = listOf(MODE_CHAT, MODE_ROLEPLAY)

    /** Настройки книги в одном месте: их читает и UI, и промпт. */
    data class Settings(
        val mode: String = MODE_CHAT,
        val matureAllowed: Boolean = false,
        val censorship: Boolean = true,
        val title: String = "",
        /** Какое издание/перевод читать — выясняет агент поиском. */
        val edition: String = "",
    )

    fun modeTitle(mode: String): String = when (mode) {
        MODE_ROLEPLAY -> MODE_ROLEPLAY_TITLE
        else -> MODE_CHAT_TITLE
    }

    /**
     * Слова, которые маскируются в режиме цензуры. Список короткий и
     * намеренно без «серьёзного» содержания: он не должен ломать перевод
     * реплик, а только смягчать грубую лексику.
     */
    val CENSOR_WORDS: List<String> = listOf(
        "блядь", "ебан", "ебать", "ебану", "хуй", "хуе", "хуя", "пизд", "мудак",
        "сука", "гандон", "дрочи", "залуп",
    )

    /**
     * Маскирует грубую лексику, сохраняя длину слова. Первая буква остаётся,
     * остальное — звёздочки: так видно, что слово было, но текст можно читать
     * вслух.
     *
     * Флаг `u` обязателен: без него `(?i)` в Java не сворачивает регистр
     * кириллицы, и «БЛЯДЬ» проходило бы мимо фильтра (проверено на JVM).
     */
    fun maskCensored(text: String, words: List<String> = CENSOR_WORDS): String {
        if (text.isEmpty() || words.isEmpty()) return text
        return censorPattern(words).replace(text) { match ->
            val word = match.value
            if (word.length <= 2) "*".repeat(word.length) else word.take(1) + "*".repeat(word.length - 1)
        }
    }

    /** Есть ли в тексте то, что нужно замаскировать (регистр кириллицы учитывается). */
    fun hasCensoredWords(text: String, words: List<String> = CENSOR_WORDS): Boolean =
        text.isNotEmpty() && censorPattern(words).containsMatchIn(text)

    private fun censorPattern(words: List<String>): Regex =
        Regex("(?iu)" + words.joinToString("|") { Regex.escape(it) })

    /**
     * Блок ограничений для промпта. Возвращает жёсткие рамки: что можно,
     * что нельзя, и в каком тоне говорить. Книжные настройки выбирает
     * читатель, поэтому модель не решает за него.
     */
    fun render(
        mode: String,
        matureAllowed: Boolean,
        censorship: Boolean,
        bookTitle: String = "",
    ): String {
        val title = bookTitle.ifBlank { "книга" }
        return buildString {
            append("РЕЖИМ РАБОТЫ С КНИГОЙ (выбрал пользователь, не обсуждается):")
            if (mode == MODE_ROLEPLAY) {
                append("\n- Тон: ты отыгрываешь персонажей «$title» и общаешься с читателем ")
                append("как собеседник в дружеской встрече: можно шутить, спорить, флиртовать ")
                append("в рамках характера героя.")
                append("\n- Знания книги при этом не теряются: сюжет, порядок чтения, ")
                append("имена и термины — как обычно, из блока знаний выше.")
                // Ремарки в скобках — не служебная разметка, а то, что
                // озвучка умеет произносить. Без этого указания модель пишет
                // прямую речь, и вздохи/крики в озвучке просто не появятся.
                append("\n- Реплику можно начать с ремарки в круглых скобках, ")
                append("она будет произнесена голосом, а не прочитана как слово: ")
                append("(вздох) (вдох) (стон) (крик) (крик помощи) (смеётся) (кашель). ")
                append("Состояние героя тоже можно указать: (шёпотом) (бегом) ")
                append("(устал) (слабость) (боль) (боюсь) (злюсь) (удивлён) — ")
                append("оно меняет тон и темп всей реплики.")
                append("\n- Междометия пиши буквами, они распознаются по длине: ")
                append("«а» — удивление, «аа» — попытка закричать, «ааа» — крик, ")
                append("«ах» — вдох или испуг.")
                append("\n- Прочей разметки не нужно: никаких тегов, списков и ")
                append("служебных пояснений, только речь и эти ремарки.")
            } else {
                append("\n- Тон: деловой помощник чтения. Коротко, по существу, без ")
                append("отыгрыша и без обращения к читателю по имени.")
            }
            if (matureAllowed) {
                append("\n- Книга помечена 18+: можешь называть зрелые темы и обсуждать их ")
                append("в рамках сюжета, без домысливания откровенных сцен.")
            } else {
                append("\n- Книга не помечена 18+: зрелые темы и постельные сцены не ")
                append("описывай и не развивай, даже если спросят прямо.")
            }
            append("\n- Запрещено всегда: сексуальный контент с несовершеннолетними, ")
            append("сексуальное насилие, отыгрыш реальных людей. Это не обсуждается ")
            append("и не отменяется настройками.")
            if (censorship) {
                append("\n- Включён фильтр грубых слов: не пиши их в ответе.")
            }
        }
    }
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.File

/**
 * Продвинутое управление историей AI-чата.
 *
 * Проблемы, которые решает:
 *  - История терялась при пересоздании вкладки / смене процесса (не было persist)
 *  - Тратил до 50к токенов на reasoning двух языков (нет лимита, нет сокращения)
 *  - Не говорил что доступно/невозможно (нет capability report)
 *
 * Решения:
 *  - Файл `workspace/ai_history.json` + StateFlow + лимит из `pref_ai_history_limit` (дефолт 12)
 *  - Токен-бюджет `pref_ai_token_budget` (дефолт 4000) — обрезка истории и max_tokens в запросе
 *  - Availability report перед каждым ходом: сеть, ключи, модели, ранер, локальная LLM
 *  - Сжатие истории: старые сообщения суммируются в краткий «контекст» вместо удаления
 */
object AiHistoryManager {

    @Serializable
    data class Msg(
        val role: String, // user | ai
        val text: String,
        val time: Long = System.currentTimeMillis(),
        val tokens: Int = 0,
        val model: String = "",
        val reasoning: String = "",
        val tools: List<String> = emptyList(),
        val files: List<String> = emptyList(),
        /** Кнопки-варианты [[...]] из ответа модели — повторная отправка текстом. */
        val choices: List<String> = emptyList(),
    )

    private const val FILE = "ai_history.json"
    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }

    private fun prefs(): OcrPreferences = Injekt.get()

    /**
     * Канал истории. У книги их два: обычный чат и отыгрыш.
     *
     * Раньше файл был один на `mangaId`, поэтому переключение режима
     * подмешивало в реплику чужой разговор: в чате могли всплыть слова
     * отыгрыша, и наоборот. У отыгрыша своя история, общие знания книги
     * при этом остаются общими — изолируется переписка, а не память.
     */
    const val CHANNEL_CHAT = "chat"
    const val CHANNEL_ROLEPLAY = "roleplay"

    fun channelOf(mode: String): String =
        if (mode == BookChatProfile.MODE_ROLEPLAY) CHANNEL_ROLEPLAY else CHANNEL_CHAT

    /**
     * Файл истории. Старые файлы книг (`ai_history_<id>.json`) остаются
     * историей обычного чата — переименовывать их не нужно, иначе читатель
     * потерял бы переписку при обновлении.
     */
    fun historyFile(context: Context, mangaId: Long? = null, channel: String = CHANNEL_CHAT): File {
        val ws = aiWorkspaceDir(context)
        ws.mkdirs()
        val target = when {
            mangaId == null -> File(ws, FILE)
            channel == CHANNEL_CHAT -> File(ws, "ai_history_${mangaId}.json")
            else -> File(ws, "ai_history_${mangaId}_$channel.json")
        }
        if (!target.exists()) migrateLegacyFile(context, target)
        return target
    }

    /**
     * Старый каталог истории: `/sdcard/Android/Yomikai/AI`.
     *
     * Именно его вычисляла прежняя версия [aiWorkspaceDir]. Файлы назывались
     * так же, поэтому достаточно перенести совпадение по имени — иначе после
     * обновления переписка просто исчезла бы, хотя нигде не удалялась.
     */
    private fun legacyDir(context: Context): File? {
        val external = context.getExternalFilesDir(null) ?: return null
        val android = external.parentFile?.parentFile ?: return null
        return File(android, "Yomikai/AI")
    }

    private fun migrateLegacyFile(context: Context, target: File) {
        val legacy = legacyDir(context) ?: return
        val old = File(legacy, target.name)
        if (!old.exists() || old.length() == 0L) return
        synchronized(saveLock) {
            try {
                // Файлы одного тома, rename атомарен; если система отказала
                // (например, каталог назначения на другом mount), копируем.
                if (!old.renameTo(target)) {
                    target.writeText(old.readText())
                    old.delete()
                }
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "AiHistoryManager legacy move failed: ${target.name}" }
            }
        }
    }

    /**
     * История лежит в корне workspace.
     *
     * Раньше папка вычислялась здесь отдельно (`getExternalFilesDir/../../Yomikai/AI`,
     * то есть `/sdcard/Android/Yomikai/AI`) и не совпадала ни с одним
     * кандидатом [AiWorkspace.root]. Из-за этого история была не видна
     * `workspace_list`/`read_file` — хотя промпт агента прямо велит читать её
     * оттуда, — и не попадала в `zip_workspace`.
     */
    private fun aiWorkspaceDir(context: Context): File = AiWorkspace.root(context)

    fun load(context: Context, mangaId: Long? = null, channel: String = CHANNEL_CHAT): MutableList<Msg> {
        val f = historyFile(context, mangaId, channel)
        if (!f.exists()) return mutableListOf()
        return try {
            val raw = f.readText()
            val list = json.decodeFromString<List<Msg>>(raw)
            // Обрезаем до лимита при загрузке
            val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
            list.takeLast(limit).toMutableList()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "AiHistoryManager load failed" }
            mutableListOf()
        }
    }

    private val saveLock = Any()

    fun save(context: Context, history: List<Msg>, mangaId: Long? = null, channel: String = CHANNEL_CHAT) {
        // Пишем через временный файл и переименовываем. Раньше шли три
        // несинхронизированных writeText() на один и тот же файл (append плюс
        // два вызова из UI), и оборванная запись оставляла битый JSON — после
        // него load() молча отдавал пустую историю, то есть вся переписка
        // исчезала без единого слова читателю.
        synchronized(saveLock) {
            try {
                val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
                val toSave = history.takeLast(limit)
                val target = historyFile(context, mangaId, channel)
                val tmp = File(target.parentFile, target.name + ".tmp")
                tmp.writeText(json.encodeToString(toSave))
                if (!tmp.renameTo(target)) {
                    target.writeText(tmp.readText())
                    tmp.delete()
                }
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "AiHistoryManager save failed" }
            }
        }
    }

    fun append(
        context: Context,
        history: MutableList<Msg>,
        msg: Msg,
        mangaId: Long? = null,
        channel: String = CHANNEL_CHAT,
    ) {
        history.add(msg)
        val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
        while (history.size > limit) {
            // Сжимаем: первые 2 сообщения → один summary
            val oldest = history.removeAt(0)
            val second = if (history.isNotEmpty()) history.removeAt(0) else null
            val summary = buildString {
                append("[Сводка прошлого контекста] ")
                append(oldest.role).append(": ").append(oldest.text.take(80))
                if (second != null) append(" | ").append(second.role).append(": ").append(second.text.take(80))
            }
            history.add(0, Msg(role = "ai", text = summary, time = System.currentTimeMillis()))
        }
        save(context, history, mangaId, channel)
    }

    /**
     * Оценка токенов грубо: 1 токен ≈ 4 символа (для ru/en). Точнее — после ответа модели.
     */
    fun estimateTokens(text: String): Int = (text.length / 3.5).toInt().coerceAtLeast(1)

    fun totalTokens(history: List<Msg>): Int = history.sumOf { if (it.tokens > 0) it.tokens else estimateTokens(it.text) }

    fun trimToBudget(history: List<Msg>, budget: Int): List<Msg> {
        if (budget <= 0) return history
        var total = totalTokens(history)
        if (total <= budget) return history
        // Убираем старые, оставляя последние дорогие
        val mutable = history.toMutableList()
        while (mutable.size > 4 && total > budget * 0.85) {
            val removed = mutable.removeAt(0)
            total -= if (removed.tokens > 0) removed.tokens else estimateTokens(removed.text)
        }
        return mutable
    }
}

package eu.kanade.tachiyomi.data.ai

import android.app.Application
import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import eu.kanade.tachiyomi.network.NetworkPreferences
import mihon.domain.ocr.service.OcrPreferences
import org.json.JSONArray
import org.json.JSONObject
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.net.HttpURLConnection
import java.net.InetSocketAddress
import java.net.Proxy
import java.net.URL
import java.util.concurrent.ConcurrentHashMap

/**
 * Онлайн AI-ассистент читалки. Два провайдера, оба OpenAI-совместимые:
 *
 * • ZEN (opencode.ai/zen) — БЕЗ API-ключа. Бесплатные текстовые модели:
 *   mimo-v2.5-free, deepseek-v4-flash-free, laguna-s-2.1-free,
 *   nemotron-3-ultra-free, nemotron-3.5-lightning-free, hy3-free,
 *   big-pickle. Space Bunny Free используется отдельным vision-OCR движком.
 *
 * • OPENROUTER — по API-ключу, выбор из бесплатных «:free» моделей
 *   (список тянется живьём с /api/v1/models и фильтруется по суффиксу).
 *
 * Используется авточтением: реплики без уверенного вердикта локальной
 * морфологии батчем уходят ассистенту на определение пола говорящего.
 */
object AiAssistant {

    const val PROVIDER_ZEN = "zen"
    const val PROVIDER_OPENROUTER = "openrouter"

    /**
     * Базовые URL встроенных провайдеров. Вынесены в константы, потому что их
     * читает реестр [AiProviders]: список в настройках обязан показывать те же
     * адреса, куда реально уходит запрос.
     */
    const val ZEN_BASE_URL = "https://opencode.ai/zen/v1"
    const val OPENROUTER_BASE_URL = "https://openrouter.ai/api/v1"

    /**
     * Модели Zen, проверенные без ключа.
     *
     * Список взят из документации opencode Zen, а не придуман: там перечислены
     * именно бесплатные модели, которые отдаются без ключа. Модели, которые
     * из неё ушли (laguna-s-2.1-free, deepseek-v4-flash-free, hy3-free),
     * выброшены — они больше не существуют, и каждая попытка получить ответ
     * была чистой потерей времени.
     *
     * Порядок = приоритет ротации: первыми идут БЫСТРЫЕ без тяжёлого
     * reasoning, reasoning-модели — в хвосте. При FreeUsageLimitError
     * (rate limit конкретной модели) запрос автоматически повторяется на
     * следующей модели списка.
     */
    val ZEN_MODELS = listOf(
        "mimo-v2.6-flash-free",
        "mimo-v2.5-free",
        "nemotron-3.5-lightning-free",
        "nemotron-3-ultra-free",
        "big-pickle",
        "space-bunny-free",
        "ling-3.0-flash-fin-free",
    )

    /** Запасной список OpenRouter :free на случай оффлайна при первом открытии. */
    val OPENROUTER_FREE_FALLBACK = listOf(
        "nvidia/nemotron-3-nano-30b-a3b:free",
        "poolside/laguna-s-2.1:free",
        "z-ai/glm-5.2:free",
        "google/gemma-4-31b-it:free",
        "nvidia/nemotron-3-super-120b-a12b:free",
    )

    private fun prefs(): OcrPreferences = Injekt.get()

    /**
     * Контекст приложения для реестров, которые читают файлы пользователя
     * (`AiProviders`, `AiPlugins`). Зарегистрирован в Injekt через
     * `AppModule.addSingleton(app)`.
     */
    private fun appContext(): Context = Injekt.get<Application>()

    /**
     * Запрос к провайдеру пользователя (любой OpenAI-совместимый endpoint:
     * Ollama, LM Studio, llama.cpp server, корпоративный прокси).
     *
     * Временные сбои ретраятся на том же адресе, как в ветке OpenRouter.
     * Автосмены на Zen здесь НАМЕРЕНО нет: пользователь явно выбрал свой
     * endpoint, и тихая отправка его промпта стороннему сервису была бы
     * неверной. Ошибка возвращается как `null` — вызывающий код деградирует
     * мягко, как и при недоступности встроенных провайдеров.
     */
    private suspend fun customProviderChat(
        spec: AiProviders.Spec,
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int,
        modelOverride: String? = null,
    ): ChatReply? {
        val url = AiProviders.chatCompletionsUrl(spec.baseUrl)
        if (url == null) {
            lastFailureMessage = "${spec.id}: некорректный baseUrl «${spec.baseUrl}»"
            logcat(LogPriority.WARN) { "Custom provider ${spec.id} has an invalid baseUrl" }
            return null
        }
        // Модель роли идёт первой: провайдер OpenAI-совместим, и человек,
        // выбравший её для роли, ждёт именно её. Свою модель оставляем
        // запасным вариантом, чтобы опечатка в id не убивала чат целиком.
        val models = listOfNotNull(modelOverride?.takeIf { it.isNotBlank() }, spec.model)
            .distinct()
        var reply: ChatReply? = null
        for (model in models) {
            var got: ChatReply? = null
            for (delayMs in longArrayOf(0, 1_200, 2_500)) {
                if (delayMs > 0) kotlinx.coroutines.delay(delayMs)
                when (val outcome = chatRawOutcome(url, model, spec.apiKey, userPrompt, systemPrompt, maxTokens)) {
                    is Outcome.Ok -> {
                        got = outcome.reply
                        break
                    }
                    Outcome.Transient -> continue
                    else -> break
                }
            }
            if (got != null) {
                reply = got
                break
            }
        }
        if (reply == null) {
            logcat(LogPriority.WARN) { "Custom provider ${spec.id} (${models.joinToString()}) did not answer" }
        }
        return reply
    }

    private val modelCooldownUntil = ConcurrentHashMap<String, Long>()

    @Volatile
    private var zenLastSuccessAt: Long = 0L

    @Volatile
    private var zenLastBlockedAt: Long = 0L

    /**
     * Что реально отвечает Zen. Отчёт о возможностях обязан опираться на
     * фактический ответ, а не на наличие сети: раньше он писал «доступно» по
     * одному факту подключения, и агент затем по инструкции «не повторяй
     * недоступное» продолжал биться в закрытую дверь вместо перехода на
     * рабочий путь.
     */
    fun zenState(): ZenAvailability.State = ZenAvailability.decide(
        lastSuccessAt = zenLastSuccessAt,
        lastBlockedAt = zenLastBlockedAt,
        now = System.currentTimeMillis(),
    )

    private fun noteZenSuccess() {
        zenLastSuccessAt = System.currentTimeMillis()
        zenLastBlockedAt = 0L
    }

    private fun noteZenBlocked() {
        zenLastBlockedAt = System.currentTimeMillis()
    }

    @Volatile
    private var lastFailureMessage: String = ""

    fun lastFailure(): String = lastFailureMessage

    /**
     * Raw AI calls used URLConnection directly and silently ignored the proxy
     * configured in Settings → Advanced. Route Zen/OpenRouter through the same
     * HTTP/SOCKS proxy, including optional Basic proxy authentication.
     */
    internal fun openConnection(url: String): HttpURLConnection {
        val network = Injekt.get<NetworkPreferences>()
        val rawHost = network.proxyHost.get().trim()
        val enabled = network.enableProxy.get() && rawHost.isNotBlank()
        val target = URL(url)
        if (!enabled) return target.openConnection() as HttpURLConnection

        val parsed = runCatching {
            val withScheme = if (rawHost.contains("://")) rawHost else "http://$rawHost"
            URL(withScheme)
        }.getOrNull()
        val host = parsed?.host?.takeIf { it.isNotBlank() }
            ?: rawHost.substringBefore(':').substringBefore('/')
        val explicitPort = parsed?.port?.takeIf { it > 0 }
            ?: rawHost.substringAfter(':', "").substringBefore('/').toIntOrNull()
        val port = explicitPort ?: network.proxyPort.get().coerceIn(1, 65_535)
        val type = if (network.proxyType.get() == 1) Proxy.Type.SOCKS else Proxy.Type.HTTP
        val connection = target.openConnection(Proxy(type, InetSocketAddress(host, port))) as HttpURLConnection
        val user = network.proxyUser.get()
        if (user.isNotBlank() && type == Proxy.Type.HTTP) {
            val credentials = "$user:${network.proxyPassword.get()}"
            val encoded = android.util.Base64.encodeToString(
                credentials.toByteArray(Charsets.UTF_8),
                android.util.Base64.NO_WRAP,
            )
            connection.setRequestProperty("Proxy-Authorization", "Basic $encoded")
        }
        return connection
    }

    private fun coolingDown(model: String): Boolean =
        (modelCooldownUntil[model] ?: 0L) > System.currentTimeMillis()

    private fun coolDown(model: String, durationMs: Long) {
        modelCooldownUntil[model] = System.currentTimeMillis() + durationMs
    }

    /** Запись скрытого AI-чата: что спросили, что ответила модель, сколько заняло. */
    data class LogEntry(
        val time: Long,
        val model: String,
        val prompt: String,
        val answer: String,
        val tookMs: Long,
    )

    /** Кольцевой журнал последних обращений — «скрытый чат» ассистента. */
    private val logBuffer = ArrayDeque<LogEntry>()

    @Synchronized
    fun log(): List<LogEntry> = logBuffer.toList()

    @Synchronized
    private fun addLog(e: LogEntry) {
        logBuffer.addLast(e)
        while (logBuffer.size > 40) logBuffer.removeFirst()
    }

    /** Живой список бесплатных моделей OpenRouter (":free"). */
    suspend fun fetchOpenRouterFreeModels(): List<String> = withContext(Dispatchers.IO) {
        runCatching {
            val conn = openConnection("$OPENROUTER_BASE_URL/models")
            conn.connectTimeout = 10_000
            conn.readTimeout = 20_000
            val body = conn.inputStream.use { it.readBytes().toString(Charsets.UTF_8) }
            conn.disconnect()
            val arr = JSONObject(body).getJSONArray("data")
            buildList {
                for (i in 0 until arr.length()) {
                    val id = arr.getJSONObject(i).optString("id")
                    if (id.endsWith(":free")) add(id)
                }
            }.sorted()
        }.getOrDefault(OPENROUTER_FREE_FALLBACK)
    }

    /** Полный ответ модели: текст, «размышления» (reasoning), реальная модель. */
    data class ChatReply(
        val content: String,
        val reasoning: String?,
        val model: String,
        /** Токены запроса+ответа (usage.total_tokens; 0 если провайдер не отдал). */
        val tokens: Int = 0,
        /** false when provider stopped because max_tokens was exhausted. */
        val complete: Boolean = true,
    )

    /**
     * Один chat-запрос выбранному провайдеру. null при любой ошибке —
     * вызывающий код обязан деградировать мягко (нейтральный голос,
     * пропуск перевода и т.п.).
     */
    suspend fun chat(userPrompt: String, systemPrompt: String? = null, maxTokens: Int = 500): String? =
        chatFull(userPrompt, systemPrompt, maxTokens)?.content

    /**
     * Как chat(), но с reasoning-блоком и именем фактически ответившей
     * модели (при автосмене может отличаться от выбранной).
     *
     * [modelOverride] — модель отдельной роли (например, оркестратора читалки).
     * Пустое значение = обычный выбор провайдера, поведение прежнее.
     */
    suspend fun chatFull(
        userPrompt: String,
        systemPrompt: String? = null,
        maxTokens: Int = 500,
        modelOverride: String? = null,
    ): ChatReply? =
        withContext(Dispatchers.IO) {
            val p = prefs()
            val provider = p.aiProvider().get()
            val override = modelOverride?.takeIf { it.isNotBlank() }

            // Провайдер пользователя из реестра AiProviders (свой base URL,
            // модель и ключ). Проверяется первым: id у него свой, поэтому ветки
            // Zen/OpenRouter ниже не затрагиваются.
            val custom = AiProviders.userProvider(appContext(), provider)
            if (custom != null) {
                return@withContext customProviderChat(
                    custom, userPrompt, systemPrompt, maxTokens, override,
                )
            }

            val key = p.openrouterApiKey().get()
            if (provider == PROVIDER_OPENROUTER && key.isNotBlank()) {
                val model = override
                    ?: p.openrouterFreeModel().get().ifBlank { OPENROUTER_FREE_FALLBACK.first() }
                if (coolingDown(model) && p.aiAutoRotate().get()) {
                    return@withContext zenChatWithRotation(userPrompt, systemPrompt, maxTokens, override)
                }
                // Временные сбои сети/прокси ретраим на той же модели,
                // прежде чем считать OpenRouter «упавшим».
                var reply: ChatReply? = null
                var lastOutcome: Outcome? = null
                for (delayMs in longArrayOf(0, 1_200, 2_500)) {
                    if (delayMs > 0) kotlinx.coroutines.delay(delayMs)
                    val outcome = chatRawOutcome(
                        "$OPENROUTER_BASE_URL/chat/completions",
                        model, key, userPrompt, systemPrompt, maxTokens,
                    )
                    lastOutcome = outcome
                    when (outcome) {
                        is Outcome.Ok -> {
                            reply = outcome.reply
                            modelCooldownUntil.remove(model)
                        }
                        Outcome.Transient -> continue
                        else -> {}
                    }
                    break
                }
                if (reply == null) {
                    // У OpenRouter свой 403 — это про конкретный ключ или
                    // модель. Дальше по коду всё равно пробуется Zen, поэтому
                    // cooldown ставится, а не выход.
                    coolDown(
                        model,
                        when (lastOutcome) {
                            Outcome.RateLimited -> 15 * 60_000L
                            Outcome.Fatal -> 5 * 60_000L
                            else -> 90_000L
                        },
                    )
                }
                if (reply != null || !p.aiAutoRotate().get()) return@withContext reply
                // Автосмена: OpenRouter реально недоступен → пробуем Zen
                return@withContext zenChatWithRotation(userPrompt, systemPrompt, maxTokens, override)
            }
            if (provider == PROVIDER_OPENROUTER) {
                logcat(LogPriority.WARN) { "OpenRouter selected but no API key; falling back to Zen" }
            }
            zenChatWithRotation(userPrompt, systemPrompt, maxTokens, override)
        }

    /**
     * Zen с авторотацией: выбранная модель первая, при rate limit / ошибке —
     * следующая из списка. Бесплатные лимиты Zen помодельные, поэтому
     * ротация почти всегда находит живую модель. Тумблер «Автосмена моделей»
     * (pref_ai_auto_rotate) ограничивает попытки одной выбранной моделью.
     */
    /**
     * Zen с ПРАВИЛЬНОЙ ротацией (фикс по жалобе пользователя):
     *  • настоящий rate limit (429/FreeUsageLimit) → сразу СЛЕДУЮЩАЯ модель;
     *  • временный сбой (таймаут/5xx/обрыв прокси) → до 2 ретраев ТОЙ ЖЕ
     *    модели с паузой 1.2с/2.5с — рабочая модель не бросается из-за
     *    моргнувшей сети;
     *  • фатальная ошибка → следующая модель.
     */
    private suspend fun zenChatWithRotation(
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int,
        preferredOverride: String? = null,
    ): ChatReply? {
        // Модель, названная ролью, идёт первой ЛЮБОЙ: каталог [ZEN_MODELS] — это
        // список для ротации, а не белый список. Раньше незнакомый id молча
        // заменялся моделью чата, и статус обещал несуществующий выбор.
        val preferred = preferredOverride?.takeIf { it.isNotBlank() }
            ?: prefs().zenModel().get().ifBlank { ZEN_MODELS.first() }
        val configuredOrder = if (prefs().aiAutoRotate().get()) {
            listOf(preferred) + ZEN_MODELS.filter { it != preferred }
        } else {
            listOf(preferred)
        }
        // A model that just returned a limit/5xx must not become first again
        // when the user taps Retry. Keep it on cooldown across chat turns.
        val order = configuredOrder.filterNot(::coolingDown).ifEmpty { configuredOrder }
        val retryDelaysMs = longArrayOf(1_200, 2_500)
        for (m in order) {
            var attempt = 0
            while (true) {
                when (val res = chatRawOutcome(
                    "$ZEN_BASE_URL/chat/completions",
                    m, "", userPrompt, systemPrompt, maxTokens,
                )) {
                    is Outcome.Ok -> {
                        modelCooldownUntil.remove(m)
                        noteZenSuccess()
                        return res.reply
                    }
                    Outcome.RateLimited -> {
                        coolDown(m, 15 * 60_000L)
                        break
                    }
                    Outcome.Fatal -> {
                        coolDown(m, 5 * 60_000L)
                        break
                    }
                    // 403 FreeTierError — это про конкретную модель, а не про
                    // весь Zen разом. Доказано тем, что OCR-движок ходит в тот
                    // же эндпоинт с той же моделью space-bunny-free и работает.
                    // Раньше здесь был выход сразу, и первая закрытая модель
                    // убивала чат целиком, не дав дойти до рабочей.
                    Outcome.FreeTierBlocked -> {
                        coolDown(m, 5 * 60_000L)
                        break
                    }
                    Outcome.Transient -> {
                        if (attempt >= retryDelaysMs.size) {
                            coolDown(m, 90_000L)
                            break
                        }
                        kotlinx.coroutines.delay(retryDelaysMs[attempt])
                        attempt++
                    }
                }
            }
        }
        return null
    }

    /**
     * Исход одного запроса. Нужен, чтобы ротация вела себя ПРАВИЛЬНО
     * (жалоба пользователя: «rate limit неверный — у одной модели
     * правильный, у другой просто сбои сети/прокси, потом отвечает»):
     *  • Ok            — ответ получен;
     *  • RateLimited   — НАСТОЯЩИЙ лимит (HTTP 429 или FreeUsageLimitError
     *                    в теле) → переключаться на следующую модель;
     *  • Transient     — временный сбой (таймаут, 5xx, обрыв соединения,
     *                    прокси) → ретраить ТУ ЖЕ модель с паузой, а не
     *                    убегать с рабочей модели;
     *  • Fatal         — постоянная ошибка модели (4xx кроме 429, кривой
     *                    ответ) → следующая модель.
     */
    private sealed class Outcome {
        data class Ok(val reply: ChatReply) : Outcome()
        object RateLimited : Outcome()
        object Transient : Outcome()
        object Fatal : Outcome()
        /**
         * Бесплатные модели Zen закрыты для сторонних клиентов самим
         * OpenCode. Закрытие помодельное, а не общее: OCR-движок в этом же
         * приложении ходит в тот же эндпоинт с моделью `space-bunny-free` и
         * получает ответ. Поэтому исход означает «пропусти эту модель», а не
         * «сдавайся» — иначе чат переставал работать из-за одной закрытой
         * модели, не дойдя до рабочей.
         */
        object FreeTierBlocked : Outcome()
    }

    /**
     * Ответ, которым OpenCode отказывает стороннему клиенту на бесплатных
     * моделях Zen: HTTP 403 c `FreeTierError` / «can only be used from within
     * OpenCode». Проверяется по телу ответа, а не по коду: 403 у провайдера
     * бывает и по другим причинам.
     */
    internal fun isZenFreeTierBlocked(code: Int, body: String): Boolean =
        code == 403 && (
            body.contains("FreeTierError", ignoreCase = true) ||
                body.contains("only be used from within OpenCode", ignoreCase = true)
            )

    /** Правдивое объяснение вместо «проверьте прокси»: прокси тут ни при чём. */
    const val FREE_TIER_BLOCKED_MESSAGE =
        "OpenCode отдаёт бесплатные модели Zen только своему собственному клиенту " +
            "(HTTP 403 FreeTierError) — ни ключ, ни прокси, ни смена модели это не лечит. " +
            "Бесплатно и легально: модели «:free» в OpenRouter (ключ бесплатный), " +
            "локальная LLM или бэкенд «Полу-онлайн», где крутится настоящий opencode."

    private fun chatRawOutcome(
        url: String,
        model: String,
        apiKey: String,
        userPrompt: String,
        systemPrompt: String?,
        maxTokens: Int = 500,
    ): Outcome {
        val startedAt = System.currentTimeMillis()
        return try {
            // Эндпоинт и форма запроса зависят от семейства модели: Claude
            // ждёт /messages, GPT и Muse — /responses, Gemini — свой путь.
            // Раньше всё уходило в /chat/completions, поэтому модели этих
            // семейств не отвечали вовсе и выглядели сломанными.
            val body = ZenProtocol.requestBody(model, userPrompt, systemPrompt, maxTokens)
            // Базовый адрес приходит от вызывающего кода с хвостом
            // /chat/completions; подставляем эндпоинт, который нужен модели.
            val actualUrl = if (url.endsWith("/chat/completions")) {
                ZenProtocol.urlFor(url.removeSuffix("/chat/completions"), model)
            } else {
                url
            }

            val conn = openConnection(actualUrl)
            conn.requestMethod = "POST"
            conn.doOutput = true
            conn.connectTimeout = 15_000
            conn.readTimeout = 90_000
            conn.setRequestProperty("Content-Type", "application/json")
            if (apiKey.isNotBlank()) conn.setRequestProperty("Authorization", "Bearer $apiKey")

            conn.outputStream.use { it.write(body.toString().toByteArray(Charsets.UTF_8)) }
            val code = conn.responseCode
            val text = (if (code in 200..299) conn.inputStream else conn.errorStream)
                ?.use { it.readBytes().toString(Charsets.UTF_8) }.orEmpty()
            conn.disconnect()
            if (code !in 200..299) {
                // Отдельная судьба для «бесплатных» моделей Zen: OpenCode
                // отдаёт их только своему же клиенту (проверка по User-Agent),
                // поэтому ни ключ, ни прокси, ни ротация тут не помогут. Ловим
                // ДО классификации по коду, иначе 403 уходит в Fatal, и каждая
                // модель каталога получает cooldown — после чего даже рабочий
                // путь выглядит сломанным на 5 минут.
                if (isZenFreeTierBlocked(code, text)) {
                    lastFailureMessage = FREE_TIER_BLOCKED_MESSAGE
                    noteZenBlocked()
                    logcat(LogPriority.WARN) { "Zen free tier blocked for $model (HTTP $code)" }
                    return Outcome.FreeTierBlocked
                }
                lastFailureMessage = "$model: HTTP $code — ${text.take(160)}"
                logcat(LogPriority.WARN) { "AI assistant HTTP $code ($model): ${text.take(160)}" }
                addLog(
                    LogEntry(
                        startedAt, model, userPrompt.take(200),
                        "HTTP $code: ${text.take(120)}",
                        System.currentTimeMillis() - startedAt,
                    ),
                )
                // Классификация: настоящий лимит vs временный сбой vs фатально
                val isLimit = code == 429 ||
                    text.contains("FreeUsageLimit", ignoreCase = true) ||
                    text.contains("rate_limit", ignoreCase = true) ||
                    text.contains("quota", ignoreCase = true)
                return when {
                    isLimit -> Outcome.RateLimited
                    code in 500..599 || code == 408 -> Outcome.Transient // 5xx/таймаут — прокси/сайт барахлит
                    else -> Outcome.Fatal
                }
            }
            // Разбор формы ответа — по семейству модели. Раньше читался
            // только choices[0].message, поэтому у Claude (блок thinking),
            // у Responses (отдельный output) и у Gemini (флаг thought)
            // размышления терялись, и в чате появлялось «🤔 null».
            val parsed = ZenProtocol.parse(text, model)
            val answer = parsed.content
            val reasoning = parsed.reasoning
            addLog(LogEntry(startedAt, model, userPrompt.take(200), (answer ?: "<пусто>").take(200), System.currentTimeMillis() - startedAt))
            answer?.let {
                lastFailureMessage = ""
                Outcome.Ok(
                    ChatReply(
                        content = it,
                        reasoning = reasoning,
                        model = model,
                        tokens = parsed.tokens,
                        complete = parsed.complete,
                    ),
                )
            } ?: Outcome.Fatal
        } catch (e: Exception) {
            lastFailureMessage = "$model: ${e.javaClass.simpleName} — ${e.message?.take(160)}"
            addLog(LogEntry(startedAt, model, userPrompt.take(200), "ОШИБКА: ${e.message?.take(120)}", System.currentTimeMillis() - startedAt))
            logcat(LogPriority.WARN, e) { "AI assistant call failed ($model)" }
            // Сетевые исключения (SocketTimeout, ConnectException, SSL,
            // UnknownHost, обрыв прокси) — ВРЕМЕННЫЕ: модель не виновата
            Outcome.Transient
        }
    }

    /** Строка подготовленного кадра: говорить ли, каким полом, каким текстом. */
    data class PreparedLine(val speak: Boolean, val gender: String?, val text: String)

    /**
     * ГЛАВНЫЙ шаг конвейера (по требованию пользователя): текст кадра
     * отправляется В ЧАТ ДО озвучки. Модель одним запросом:
     *  1) вычищает реплики, повторяющие прошлый кадр (перекрытие скролла);
     *  2) назначает пол говорящего каждой оставшейся;
     *  3) возвращает чистый текст для синтеза.
     * Протокол ответа — по строке на реплику: «N|г|текст» (г: м/ж/н) или
     * «N|-» для пропуска дубля. Всё видно в скрытом чате (журнале).
     * Таймаут 8с: при сбое вызывающий код откатывается на локальный конвейер.
     */
    suspend fun prepareFrame(newLines: List<String>, prevLines: List<String>, advice: String? = null): List<PreparedLine>? {
        if (newLines.isEmpty()) return emptyList()
        val prevBlock = if (prevLines.isEmpty()) {
            "(прошлый кадр пуст)"
        } else {
            prevLines.takeLast(20).joinToString("\n") { "- ${it.take(90)}" }
        }
        val newBlock = newLines.mapIndexed { i, t -> "${i + 1}. ${t.take(140)}" }.joinToString("\n")
        val adviceBlock = advice?.let { "\n\nСоветы читателя (соблюдай): $it" }.orEmpty()
        val answer = kotlinx.coroutines.withTimeoutOrNull(8_000) {
            chat(
                userPrompt = "Прошлый кадр манги содержал реплики:\n$prevBlock\n\n" +
                    "Новый кадр:\n$newBlock$adviceBlock\n\n" +
                    "Для КАЖДОЙ реплики нового кадра ответь отдельной строкой строго в формате " +
                    "«N|г|текст», где N — номер, г — пол говорящего (м/ж/н), " +
                    "текст — реплика, очищенная от мусора OCR. Если реплика повторяет прошлый кадр " +
                    "(даже частично/с искажениями) — ответь «N|-». Больше НИЧЕГО не пиши.",
                systemPrompt = "Ты конвейер озвучки манги: чистишь повторы и назначаешь пол. " +
                    "Отвечаешь только строками формата N|г|текст или N|-.",
                maxTokens = 600,
            )
        } ?: return null

        val byIndex = HashMap<Int, PreparedLine>()
        for (line in answer.lines()) {
            val parts = line.trim().split('|', limit = 3)
            val n = parts.getOrNull(0)?.trim()?.toIntOrNull() ?: continue
            if (n !in 1..newLines.size) continue
            if (parts.size < 2 || parts[1].trim() == "-") {
                byIndex[n] = PreparedLine(speak = false, gender = null, text = "")
                continue
            }
            val gender = when (parts[1].trim().lowercase()) {
                "м" -> "male"
                "ж" -> "female"
                else -> null
            }
            val text = parts.getOrNull(2)?.trim().orEmpty().ifBlank { newLines[n - 1] }
            byIndex[n] = PreparedLine(speak = true, gender = gender, text = text)
        }
        if (byIndex.isEmpty()) return null // модель ответила не по протоколу
        return List(newLines.size) { i ->
            byIndex[i + 1] ?: PreparedLine(speak = true, gender = null, text = newLines[i])
        }
    }

    /**
     * Пол говорящих — СВЕРХБЫСТРЫЙ формат: модель отвечает строкой из букв,
     * по одной на реплику: «м» (мужской), «ж» (женский), «н» (не ясно).
     * Никакого JSON и рассуждений: max_tokens=40, ответ приходит за долю
     * секунды даже у reasoning-моделей. Плюс жёсткий таймаут 6с — если сеть
     * тупит, чтение продолжается нейтральным голосом, а не ждёт модель.
     * Фолбэк: локальный словарь морфологии (LocalSpeakerAi) уже отработал
     * ДО этого вызова — сюда приходят только реплики без вердикта.
     */
    suspend fun detectGendersByText(lines: List<String>): List<String?> {
        if (lines.isEmpty()) return emptyList()
        val numbered = lines.mapIndexed { i, t -> "${i + 1}) ${t.take(100)}" }.joinToString("\n")
        val answer = kotlinx.coroutines.withTimeoutOrNull(6_000) {
            chat(
                userPrompt = "Кто говорит каждую реплику? Ответь ТОЛЬКО строкой из ${lines.size} букв " +
                    "без пробелов: м=мужчина, ж=женщина, н=неясно. Пример ответа: мжнм\n\n" + numbered,
                systemPrompt = "Отвечай только буквами м/ж/н, ничего больше. Без рассуждений.",
                maxTokens = 40,
            )
        } ?: return List(lines.size) { null }

        // Берём последнюю строку ответа (reasoning-модели любят префиксы),
        // выбрасываем всё, кроме м/ж/н
        val letters = answer.lines().lastOrNull { l -> l.any { it in "мжн" } }
            ?.filter { it in "мжн" }.orEmpty()
        return List(lines.size) { i ->
            when (letters.getOrNull(i)) {
                'м' -> "male"
                'ж' -> "female"
                else -> null
            }
        }
    }
}

