        var terminalUrl: String? = null,
        /** ОС ранера: linux | windows. */
        var os: String = "linux",
        val messages: MutableList<Pair<String, String>> = mutableListOf(), // role -> content
        var createdAt: Long = System.currentTimeMillis(),
    )

